// Normaliza lo que envía el formulario de fidelmercadotech.com, lo sanea y decide si es válido.
// El webhook es público: cualquiera puede llamarlo sin pasar por el formulario, así que aquí se valida de nuevo todo.
const b = $input.first().json.body ?? $input.first().json;

// Una sola línea: sin saltos ni caracteres de control (evita inyectar cabeceras en el correo).
const line = (v, n) => String(v ?? "").replace(/[\u0000-\u001F\u007F\u2028\u2029]+/g, " ").replace(/\s+/g, " ").trim().slice(0, n);
// Varias líneas: conserva los saltos de línea y elimina el resto de caracteres de control.
const text = (v, n) => String(v ?? "").replace(/\r\n?/g, "\n").replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F\u2028\u2029]/g, "").trim().slice(0, n);
// Si empieza como una fórmula de hoja de cálculo (=, @, o +/- seguido de letra o paréntesis), se antepone un apóstrofo.
// Los teléfonos como "+57 300..." no se tocan. (La hoja además se escribe en modo RAW.)
const safe = (s) => (/^[=@]/.test(s) || /^[+\-]\s*[A-Za-z(]/.test(s) ? "'" + s : s);

const MOTIVOS = ["demo", "proyecto", "automatizacion", "ia", "otro"];
const email = line(b.email, 160).toLowerCase();
const motivo = line(b.motivo, 40);

const out = {
  fecha: new Date().toLocaleString("es-CO", { timeZone: "America/Bogota" }),
  nombre: safe(line(b.nombre, 120)),
  empresa: safe(line(b.empresa, 160)),
  email,
  telefono: safe(line(b.telefono, 40)),
  motivo: MOTIVOS.includes(motivo) ? motivo : "otro",
  interes: safe(line(b.interes, 80)),
  mensaje: safe(text(b.mensaje, 3000)),
  origen: "fidelmercadotech.com",
  estado: "Nuevo",
};
out.ok =
  out.nombre.length >= 2 &&
  /^[A-Za-z0-9._%+-]{1,64}@[A-Za-z0-9-]+(\.[A-Za-z0-9-]+)*\.[A-Za-z]{2,}$/.test(email) &&
  out.mensaje.length >= 10 &&
  b.consentimiento === true &&
  !b.website; // campo trampa: un humano nunca lo llena
return [{ json: out }];

